 public sealed partial class MainWindow : Window {
  readonly Grid body=new Grid();readonly TextBlock title=new TextBlock{FontSize=26};readonly TextBlock status=new TextBlock{Foreground=Brushes.Turquoise};readonly StackPanel navigation=new StackPanel();readonly string root;ClientSession session;bool busy,closing,closeRequested,healthPolling;readonly bool diagnostic;string current="Главная";readonly DispatcherTimer health=new DispatcherTimer{Interval=TimeSpan.FromSeconds(2)};
  public MainWindow(string[] args){diagnostic=args.Contains("--data")&&!args.Contains("--interactive");Title="MCRF";Width=1366;Height=865;MinWidth=1050;MinHeight=680;WindowStartupLocation=WindowStartupLocation.CenterScreen;Width=Math.Min(Width,SystemParameters.WorkArea.Width-32);Height=Math.Min(Height,SystemParameters.WorkArea.Height-32);MinWidth=Math.Min(MinWidth,Width);MinHeight=Math.Min(MinHeight,Height);Background=Brush("#0C111F");Foreground=Brush("#EDF2FF");FontFamily=new FontFamily("Segoe UI");FontSize=13;System.Windows.Media.TextOptions.SetTextFormattingMode(this,System.Windows.Media.TextFormattingMode.Display);System.Windows.Media.TextOptions.SetTextRenderingMode(this,System.Windows.Media.TextRenderingMode.Grayscale);UseLayoutRounding=true;SnapsToDevicePixels=true;root=args.Length>1&&args[0]=="--data"?Path.GetFullPath(args[1]):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"mcrf-wpf");SetBrand();BuildShell();Loaded+=async(s,e)=>{status.Text="Загрузка отдельного профиля…";try{session=await ClientSession.Open(root);session.BeforeVpnStart=()=>DownloadCsqttRequirements(session.State.Servers.Where(n=>!WarpPicker.IsWarp(n)&&(session.State.AutoSelect?(session.Core.HasEngine(n)||n.Protocol=="csqtt"&&session.Core.CSQTTExecutableFor(n)!=null||n.Protocol=="qwdtt"&&session.Core.QwdttExecutable!=null):n.Id==session.State.SelectedServerId)),false);session.Core.ManualTurnCaptcha=(url,cancel)=>VkPage(url,true,cancel);if(closing){await Task.Run(()=>session.Dispose());return;}if(!closing){if(!diagnostic)startupEnabled=await Task.Run(()=>WpfWindowsStartup.Enabled);status.Text="MCRF готов.";ApplyInterfaceMode();Page("Главная");RegisterHotkeys();SyncModules();health.Start();if(args.Length==0||args.Contains("--interactive")){InstallTray();if(session.Updates.Preferences.CheckOnStart)CheckStartupUpdates();if(!session.State.SetupSeen&&InterfaceMode!=1)ScheduleFirstSetup();}}}catch(Exception ex){status.Text=ex.Message;}};health.Tick+=async(s,e)=>await PollHealth();Closing+=async(s,e)=>{if(closing)return;if(!forceExit&&session!=null&&session.State.CloseToTray&&tray!=null){e.Cancel=true;Hide();return;}e.Cancel=true;if(busy){closeRequested=true;if(session!=null&&session.Core.Starting)CancelCoreStartup();if(scanCancellation!=null)scanCancellation.Cancel();if(warpCancellation!=null)warpCancellation.Cancel();if(deploymentCancellation!=null)deploymentCancellation.Cancel();status.Text="Останавливаем проверку. Окно закроется после завершения отмены.";return;}closing=true;health.Stop();if(hotkeys!=null)hotkeys.Dispose();IsEnabled=false;try{if(session!=null)await Task.Run(()=>session.Dispose());}catch(Exception ex){status.Text="Ошибка завершения: "+ex.Message;}finally{if(tray!=null){tray.Visible=false;tray.Dispose();}Close();}};}
  static SolidColorBrush Brush(string hex){var brush=(SolidColorBrush)new BrushConverter().ConvertFromString(hex);brush.Freeze();return brush;}
  static TextBlock Text(string text,double size=13){return new TextBlock{Text=text,FontSize=size>16?size*.86:size,Margin=new Thickness(0,0,0,8),TextWrapping=TextWrapping.Wrap,Foreground=Brush(size>=18?"#EDF2FF":"#BFCCE2")};}
  Button Button(string text,Action action,bool allowBusy=false){var button=new Button{Content=text};button.Click+=(s,e)=>{if(!busy||allowBusy||Window.GetWindow(button)!=this)try{action();}catch(Exception ex){status.Text=ex.Message;RecordEvent("Ошибка: "+ex.Message);}};return button;}
  Button AsyncButton(string text,Func<Task> action){return Button(text,async()=>await Run(action));}
  Button NavButton(string label){var button=Button(label,()=>Page(label));button.Height=36;button.FontSize=13;button.Margin=new Thickness(0,0,10,6);button.Padding=new Thickness(12,6,12,6);return button;}
  async Task Run(Func<Task> action,Action rollback=null){if(busy)return;var previousState=session==null?null:session.State;busy=true;navigation.IsHitTestVisible=false;SyncModules();try{await action();if(!String.IsNullOrWhiteSpace(status.Text))RecordEvent(status.Text);}catch(OperationCanceledException){status.Text="Операция отменена. Изменения не применены.";}catch(Exception ex){status.Text=ex.Message;RecordEvent("Ошибка: "+ex.Message);if(session!=null&&!Object.ReferenceEquals(previousState,session.State)){if(rollback==null)RebuildAfterRollback(ex.Message);else rollback();}}finally{busy=false;navigation.IsHitTestVisible=true;SyncModules();CompleteUiRecovery();ScheduleTunIntent();ScheduleInterfaceMode();if(closeRequested)Close();}}
  Border Card(UIElement child){return new Border{Background=(Brush)FindResource("CardSurface"),BorderBrush=Brush("#152B3B56"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(18),Padding=new Thickness(16),Child=child};}
  static DataGrid Table(object data,params string[] mappings){var table=new DataGrid{ItemsSource=(System.Collections.IEnumerable)data};foreach(string mapping in mappings){string[] pair=mapping.Split('|');table.Columns.Add(new DataGridTextColumn{Header=pair[0],Binding=new Binding(pair[1]),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});}return table;}
  readonly List<string> pageHistory=new List<string>();int historyIndex=-1;bool traversingHistory;
  void NavigateHistory(int offset){if(busy)return;int next=historyIndex+offset;if(next<0||next>=pageHistory.Count)return;historyIndex=next;traversingHistory=true;try{Page(pageHistory[next]);}finally{traversingHistory=false;}}
  void Page(string name){if(session==null||busy)return;if(name=="Серверы VPN"||name=="WARP"&&InterfaceMode==0)name="Серверы";if(!PageAvailable(name))name=DefaultInterfacePage;if(name=="Zapret")name="Zapret & Byetube";if(name=="Подключение"||name=="hosts")name=DefaultInterfacePage;if(!traversingHistory&&(historyIndex<0||pageHistory[historyIndex]!=name)){if(historyIndex+1<pageHistory.Count)pageHistory.RemoveRange(historyIndex+1,pageHistory.Count-historyIndex-1);pageHistory.Add(name);historyIndex=pageHistory.Count-1;}current=name;side.Visibility=name=="Главная"&&InterfaceMode==0?Visibility.Collapsed:Visibility.Visible;sidebarColumn.Width=new GridLength(name=="Главная"&&InterfaceMode==0?0:202);refreshHome=null;refreshServer=null;refreshLog=null;title.Visibility=name=="Главная"?Visibility.Collapsed:Visibility.Visible;foreach(Button item in navigation.Children){bool selected=Convert.ToString(item.Content)==name||(name=="Генератор стратегий"||name=="Редактор стратегий"||name=="Результаты")&&Convert.ToString(item.Content)=="Zapret & Byetube";item.Background=selected?Brush("#A542376B"):Brushes.Transparent;item.HorizontalContentAlignment=HorizontalAlignment.Left;}title.Text=name;status.Text="";body.Children.Clear();if(name=="Главная")Dashboard();else if(name=="Конструктор")SimplePresetPage("proxy");else if(name=="WARP")SimpleWarpPage();else if(name=="Серверы")ServersWorkspace();else if(name=="Маршрутизация")RoutedListsPage();else if(name=="Шаблоны игр")Templates();else if(name=="Zapret & Byetube")ZapretPage();else if(name=="Редактор стратегий")FullStrategyEditor();else if(name=="Генератор стратегий")GeneratorPage();else if(name=="Результаты")ResultsPage();else if(name=="Мастер настройки")SetupPage();else if(name=="Обновления")UpdatesPage();else if(name=="Автодеплой")DeploymentPage();else if(name=="VK TURN")VkTurnPage();else Journal();body.Opacity=1;}
  void RefreshAfterOperation(string page){Dispatcher.BeginInvoke(new Action(()=>{if(!closing)Page(page);}),DispatcherPriority.Background);}
  void ZapretPage(){ZapretWorkspace();}
  void Journal(){JournalWorkspace();}
  Window Dialog(string heading,double width,double height){return new WorkspaceDialog{Title=heading,Owner=this,Icon=Icon,Width=Math.Min(width,Math.Min(ActualWidth-48,SystemParameters.WorkArea.Width-48)),Height=Math.Min(height,Math.Min(ActualHeight-48,SystemParameters.WorkArea.Height-48)),WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Brushes.Transparent,Foreground=Foreground,FontFamily=FontFamily,FontSize=13,Resources=Resources};}
  string Input(string heading,string hint,bool multiline,string initial=""){var window=Dialog(heading,800,multiline?560:280);var panel=new DockPanel{Margin=new Thickness(24)};var label=Text(hint);DockPanel.SetDock(label,Dock.Top);panel.Children.Add(label);var text=new TextBox{Text=initial,AcceptsReturn=multiline,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto};var actions=Toolbar(Button("Готово",()=>window.DialogResult=true),Button("Отмена",()=>window.DialogResult=false));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);panel.Children.Add(text);window.Content=panel;window.Loaded+=(s,e)=>text.Focus();return window.ShowDialog()==true?text.Text:null;}
